def amount_due(invoice):
    """Return the invoice total in integer cents."""
    return (
        invoice["subtotal_cents"] + invoice["shipping_cents"]
    ) * (100 - invoice["discount_percent"]) // 100

from pricing import amount_due


def quote_invoice(subtotal_cents, shipping_cents, discount_percent):
    invoice = {
        "subtotal_cents": subtotal_cents,
        "shipping_cents": shipping_cents,
        "discount_percent": discount_percent,
    }
    return {"total_cents": amount_due(invoice)}

from pricing import amount_due


def render_receipt(subtotal_cents, shipping_cents, discount_percent):
    invoice = {
        "subtotal_cents": subtotal_cents,
        "shipping_cents": shipping_cents,
        "discount_percent": discount_percent,
    }
    total = amount_due(invoice)
    return f"Total: {total} cents"

